-- SessionIQ online service schema.
-- Everything here is a running total or a small per-player row, so storage grows with the
-- number of players and servers, never with how long people play.

-- Anonymous launch counter. The id is a random UUID generated by the mod on first launch;
-- it is not linked to a Minecraft account.
CREATE TABLE installs (
	id TEXT PRIMARY KEY,
	first_seen INTEGER NOT NULL,
	last_seen INTEGER NOT NULL,
	launches INTEGER NOT NULL DEFAULT 0,
	mod_version TEXT,
	mc_version TEXT
);
CREATE INDEX installs_last_seen ON installs (last_seen);

-- One row per UTC day.
CREATE TABLE daily (
	day TEXT PRIMARY KEY,
	launches INTEGER NOT NULL DEFAULT 0,
	active INTEGER NOT NULL DEFAULT 0,
	new_installs INTEGER NOT NULL DEFAULT 0
);

-- Signed-in players (Minecraft accounts verified with their Mojang-signed player key).
CREATE TABLE players (
	uuid TEXT PRIMARY KEY,
	name TEXT NOT NULL,
	name_lower TEXT NOT NULL,
	created_at INTEGER NOT NULL,
	updated_at INTEGER NOT NULL,
	last_seen INTEGER,
	online INTEGER NOT NULL DEFAULT 0,
	current_server TEXT,
	share_stats INTEGER NOT NULL DEFAULT 1,
	show_online INTEGER NOT NULL DEFAULT 1,
	show_server INTEGER NOT NULL DEFAULT 1,
	show_stats INTEGER NOT NULL DEFAULT 1,
	allow_chat INTEGER NOT NULL DEFAULT 1,
	playtime_ms INTEGER NOT NULL DEFAULT 0,
	sessions INTEGER NOT NULL DEFAULT 0,
	servers_joined INTEGER NOT NULL DEFAULT 0,
	total_joins INTEGER NOT NULL DEFAULT 0,
	top_server TEXT,
	top_server_ms INTEGER NOT NULL DEFAULT 0,
	stats_at INTEGER
);
CREATE INDEX players_name ON players (name_lower);
CREATE INDEX players_leaderboard ON players (share_stats, playtime_ms DESC);

-- A player's totals on each public server. Used to keep the server totals exact when a
-- player re-syncs (only the difference is applied).
CREATE TABLE player_servers (
	uuid TEXT NOT NULL,
	host TEXT NOT NULL,
	playtime_ms INTEGER NOT NULL,
	joins INTEGER NOT NULL,
	PRIMARY KEY (uuid, host)
);

CREATE TABLE servers (
	host TEXT PRIMARY KEY,
	playtime_ms INTEGER NOT NULL DEFAULT 0,
	joins INTEGER NOT NULL DEFAULT 0,
	players INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX servers_playtime ON servers (playtime_ms DESC);
CREATE INDEX servers_joins ON servers (joins DESC);

-- The precomputed Global Statistics response, refreshed by the cron trigger.
CREATE TABLE snapshot (
	id INTEGER PRIMARY KEY CHECK (id = 1),
	json TEXT NOT NULL,
	at INTEGER NOT NULL
);

-- Friendships are stored in both directions (a -> b and b -> a).
CREATE TABLE friendships (
	a TEXT NOT NULL,
	b TEXT NOT NULL,
	since INTEGER NOT NULL,
	PRIMARY KEY (a, b)
);

CREATE TABLE friend_requests (
	from_uuid TEXT NOT NULL,
	to_uuid TEXT NOT NULL,
	at INTEGER NOT NULL,
	PRIMARY KEY (from_uuid, to_uuid)
);
CREATE INDEX friend_requests_to ON friend_requests (to_uuid);

CREATE TABLE blocks (
	uuid TEXT NOT NULL,
	blocked TEXT NOT NULL,
	at INTEGER NOT NULL,
	PRIMARY KEY (uuid, blocked)
);

-- Friend chat. Messages are deleted after MESSAGE_RETENTION_DAYS.
CREATE TABLE messages (
	id INTEGER PRIMARY KEY AUTOINCREMENT,
	from_uuid TEXT NOT NULL,
	to_uuid TEXT NOT NULL,
	text TEXT NOT NULL,
	at INTEGER NOT NULL,
	read INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX messages_to ON messages (to_uuid, read);
CREATE INDEX messages_from ON messages (from_uuid, at);
CREATE INDEX messages_at ON messages (at);

CREATE TABLE suggestions (
	id INTEGER PRIMARY KEY AUTOINCREMENT,
	at INTEGER NOT NULL,
	install_id TEXT NOT NULL,
	player TEXT,
	category TEXT NOT NULL,
	text TEXT NOT NULL,
	mod_version TEXT,
	status TEXT NOT NULL DEFAULT 'new'
);
CREATE INDEX suggestions_install ON suggestions (install_id, at);
CREATE INDEX suggestions_status ON suggestions (status, id);
